# -*- coding: utf-8 -*-
"""fold_dix1_r121.py -- fold deviation D-IX-1 (the amended instruction, version 2; the extended gate; the re-derived cue list;
the reduced check design) into the registration draft. Whole-paragraph replacements, each asserted to match exactly once. No call."""
import io
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[3]
P = ROOT / "reviews" / "r121" / "registrations_draft" / "ADDENDUM_CF2_INTENT_CROSSOVER.md"
lines = io.open(P, encoding="utf-8").read().split("\n")


def replace_line(prefix, new):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, (prefix, len(idx))
    lines[idx[0]] = new


replace_line("**Renderer** (`reviews/r121/tools/cross_questions.py`, prompt sha256 `5c15f5ba",
    "**Renderer** (`reviews/r121/tools/cross_questions.py`, instruction **version 2** under deviation D-IX-1 of `reviews/r121/DEVIATIONS_R121.md`; prompt sha256 `ee92835120c2f76891e02cdbde2fadc8976bc1258d1fcfca7aa8d20d31b809f9` over SYSTEM, USER, model, temperature, both seeds and max_tokens): gpt-4.1-mini, temperature 0, max_tokens 200, one question per call; the prompt sees the entity's display name, the slot attribute path (`slot_key[1]`, as the CF renderer saw it) and the crossed time-sense, and never the entry text or any value, the category, the original question, any store content or any label. The instruction requires the first person (\"my\", \"I\"; never \"your\" for the user, never a name, never what someone thinks); population A asks how the attribute has changed over time with no invented window; population B asks, in the past tense, what the event was or when it took place, never how it went. Seed 42 at temperature 0 is the primary draft. The one fallback is a **registered second lineage** (Phase 1 ruling 2): the same instruction and model, **temperature 0.7, seed 4242**, one question per pair, through the same automatic gate and the same leak screen (lineage sha256 `090d796e05ff5bc215809cca560aef89135407c699bf3541e72871546b48ee92` over the same seven fields with the temperature 0.7). Both are drafted for every pair up front so that the author's check reads one workbook (ruling 5). The lineage stays cue-bearing on purpose, so the population remains homogeneous; a cue-free population is an open item, not part of this registration. Version 1 of the instruction (prompt sha `5c15f5ba…`, lineage sha `3fd41897…`) and its questions, and the temperature-0 fallback that lineage 2 replaced (byte-identical to its primary on 98 of 118), are kept in the records (`build/superseded/`; D-IX-1). The instruction's CHANGE and PAST paragraphs are quoted in `cross_questions.py`; the cue list of §6 is proposed from them and from nothing else.")

replace_line("**Automatic gate** (a construction rule",
    "**Automatic gate** (a construction rule, applied to every drafted question before the author's check; a rejection is a failure of that draft, and the rejection counts are reported): G1 no frozen FUTURE marker of `e1_metamemory/tools/intent.py` fires; G2 the question is not byte-identical to the original; G3 the JSON parses to a non-empty question; G4 no second person (you, your, yours, yourself); G5 no token of the persona's display name; G6 no time-window phrase (`TIME_WINDOW` in the module, fixed before any version-2 question was drafted). The gate does not use the cue list.")

replace_line("**Author check (disclosed as such), all 118 pairs, before any monitor call.**",
    "**Author check (disclosed as such; AI-assisted, every verdict the author's), before any monitor call, under the reduced design.** The checked set is all 30 pairs of population B, every population-A pair whose seed-42 question is off the modal template (the most frequent form of the A questions after masking to their first three and last three words), and a seeded 20 of the conforming A pairs (`random.Random(42).sample` over the sorted pair_ids); the remaining conforming A pairs are the reserve, checked in full only if any sampled row fails. One workbook (`reviews/r121/build/AUTHOR_CHECK_R121.xlsx`, sha256 recorded at build and again as returned), five tabs: `seed42` (the checked set, the seed-42 question), `seed4242` (the checked set, the second lineage's question, consulted only for the rows the author failed on `seed42`, and the workbook says so at its top), `reserve_seed42` and `reserve_seed4242` (the reserve, the same rule), `CRITERIA`. The author judges every checked seed-42 question first and never chooses between two passing candidates; a draft the gate rejected is shown as such and is not a candidate; the rows that used the second seed are recorded (AUX-CF2-IX-CHECK). Each tab carries four YES/NO columns: (i) it asks about change or history (A) or, in the past tense, about what the event was or when it took place (B); (ii) under Definition 1 the old content is a proper part of its answer; (iii) it names no stored value (the value of the attribute as the pair's entry text or its PN successor records it; naming the slot's topic as the attribute path names it is allowed, the CF renderer's own rule; ruling 3); (iv) it concerns the same attribute as the original. A question passes only on four YES. A pair whose fallback also fails, was gate-rejected, or is byte-identical to the primary (reported, not greyed), is **dropped**. Drops are reported with their reasons (AUX-CF2-IX-DROPS) and the populations shrink accordingly; no replacement is drawn. A conforming A pair in the reserve that is never checked is taken as passing under the sampled 20 (the reduced design); if any sampled row fails, the reserve is checked in full. The verdicts are the author's; the workbook is the record.")

replace_line("## §6: The cue list (fixed here, before any question exists; `reviews/r121/tools/cue_list.py`, sha256 `bf063a8e",
    "## §6: The cue list (fixed here, before any question exists; `reviews/r121/tools/cue_list.py` version 2, sha256 `a63461d09d5c60c44009c05b004657394a854ab10d468f80bf9377625f8fb9a8`; version 1, `bf063a8e…`, superseded with the instruction under D-IX-1 and kept in the module with its hash asserted)")

replace_line("Thirty regular expressions, case-insensitive after NFKD folding",
    "Twenty-six regular expressions, case-insensitive after NFKD folding, proposed from the version-2 instruction text only, before any version-2 question was generated, and kept untuned (ruling 4): the twelve PAST markers of `intent.py` (the paper's Rule 2.1), imported; ten CHANGE cues from the renderer's CHANGE paragraph (`how has|have`, `change|changed`, `changes`, `changing`, `history`, `use|used to`, `before`, `previously`, `over time`, `earlier`); four PAST cues from its PAST paragraph (`happen|happened`, `when was`, `what was`, `have|had planned`). Disclosure, computed before the regeneration on the 148 recorded original questions: three fire (`before` on kofi `preparation_for_meeting`, an UPCOMING question; `history` on valentina `hobby:history_podcasts`, a CURRENT question; `have|had planned` on rosa `project:colada_taste_test`, a retraction pair outside the populations); they stay, as the keyword lookup's false zeros on the recorded cells, and are reported (AUX-CF2-IX-CUES).")

io.open(P, "w", encoding="utf-8", newline="\n").write("\n".join(lines))
print("folded 5 paragraphs")
